// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        address currentOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.setOwner(actor) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        address expectedOwner;
        if (actor == currentOwner) {
            expectedOwner = actor;
        } else {
            expectedOwner = currentOwner;
        }

        assertTrue(c.owner() == expectedOwner);
    }
}
